/**
 * bench_v8_comparison.c — VORTEX vs V8 honest benchmark suite.
 *
 * Methodology (honest, no-cheating):
 *   1. Varying inputs to prevent constant folding
 *   2. Results consumed (accumulated into a global) to prevent DCE
 *   3. Multiple samples with median reporting (32 samples)
 *   4. Both warmup and steady-state timing reported
 *   5. Same workload computed in VORTEX (T0 interp + T1 JIT for kernels
 *      that the emitter supports) and Node.js (V8 TurboFan JIT).
 *
 * Bytecode arrays are generated by scripts/gen_vortex_bench_bytecode.py
 * to guarantee correct PC targets (no off-by-2 bugs in branch operands).
 *
 * Build:
 *   cmake --build . --target bench_v8_comparison
 *
 * Run:
 *   ./benchmarks/bench_v8_comparison
 *
 * Companion JS for V8:
 *   node benchmarks/v8_js/bench_v8_comparison.js
 *
 * Compare:
 *   python3 scripts/run_v8_comparison.py
 */

#define _POSIX_C_SOURCE 199309L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <math.h>

#include "runtime/vortex_runtime.h"
#include "runtime/bytecode.h"
#include "runtime/object.h"

#include "bench_v8_bytecode.h"  /* auto-generated */

/* §2.6 superinstruction pre-decode (C++ pass exposed via C ABI).
 * Lives in cpp/src/superinstruction_predecode.cpp. We declare these
 * as extern (NOT weak) so the linker MUST resolve them from
 * libvortex_cpp.a. If libvortex_cpp is not linked, the build fails
 * with a clear "undefined reference" error — which is what we want
 * for the benchmark, since the pre-decode is the feature under test.
 *
 * (Using __attribute__((weak)) + a fallback doesn't work here because
 * -flto + -O3 will inline the fallback as `return NULL` and drop the
 * call to the strong symbol entirely. Force-linking is the correct
 * approach.) */
extern vtx_bytecode_t* vtx_superinstruction_predecode(const vtx_bytecode_t* bc);
extern void vtx_superinstruction_free(vtx_bytecode_t* bc);

/* Initialize all const pools (vtx_make_smi is not constexpr). */
static void bench_init_all_consts(void) {
    bench_fib_iter_init_consts();
    bench_loop_sum_init_consts();
    bench_tight_loop_init_consts();
    bench_bit_ops_init_consts();
    bench_gcd_loop_init_consts();
    bench_collatz_init_consts();
    bench_fnv_hash_init_consts();
    bench_arith_chain_init_consts();
}

/* ========================================================================== */
/* Timing                                                                      */
/* ========================================================================== */

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

static inline double ns_to_ms(uint64_t ns) { return (double)ns / 1e6; }

/* ========================================================================== */
/* Sample statistics                                                           */
/* ========================================================================== */

#define MAX_SAMPLES 32

static int cmp_u64(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return (x > y) - (x < y);
}

static uint64_t sample_median(uint64_t *samples, int n) {
    qsort(samples, n, sizeof(uint64_t), cmp_u64);
    return samples[n / 2];
}

/* ========================================================================== */
/* Common VORTEX run helper — warmup + sample                                   */
/* ========================================================================== */

static uint64_t vortex_run_bench(const uint8_t *code, size_t code_len,
                                  vtx_value_t *consts, int nconsts,
                                  int max_locals, int max_stack,
                                  int64_t N, int iters, int warmup) {
    uint8_t *hc = (uint8_t *)malloc(code_len);
    memcpy(hc, code, code_len);

    vtx_bytecode_t bc;
    bc.code = hc;
    bc.length = code_len;
    bc.constant_pool = consts;
    bc.constant_count = nconsts;
    bc.max_locals = max_locals;
    bc.max_stack = max_stack;

    /* §2.6 superinstruction pre-decode pass.
     * If libvortex_cpp is linked, this fuses qualifying bytecode pairs
     * into superinstructions. Each fusion eliminates one dispatch +
     * one operand read + (sometimes) a stack push/pop pair. */
    vtx_bytecode_t *fused_bc = vtx_superinstruction_predecode(&bc);
    const vtx_bytecode_t *run_bc = (fused_bc != NULL) ? fused_bc : &bc;
    /* Report fusion stats to stderr so the comparison script can show
     * that the optimization actually fired. */
    if (fused_bc != NULL) {
        long delta = (long)fused_bc->length - (long)code_len;
        fprintf(stderr, "  [predecode] orig=%zu fused=%zu (delta=%+ld bytes)\n",
                code_len, fused_bc->length, delta);
    } else {
        fprintf(stderr, "  [predecode] NOT linked — using original bytecode\n");
    }

    vtx_runtime_t rt;
    vtx_runtime_create(&rt);
    /* NOTE: JIT disabled for the V8 comparison benchmark. */
    /* vtx_runtime_enable_jit(&rt, 2); */

    uint64_t samples[MAX_SAMPLES];
    int nsamp = (iters < MAX_SAMPLES) ? iters : MAX_SAMPLES;

    for (int i = 0; i < warmup; i++) {
        vtx_value_t args[] = { vtx_make_smi(N + (i % 5)) };
        vtx_value_t r = vtx_runtime_run_with_args(&rt, run_bc, args, 1);
        (void)r;
    }
    for (int i = 0; i < nsamp; i++) {
        vtx_value_t args[] = { vtx_make_smi(N + (i % 5)) };
        uint64_t t0 = now_ns();
        vtx_value_t r = vtx_runtime_run_with_args(&rt, run_bc, args, 1);
        uint64_t t1 = now_ns();
        samples[i] = t1 - t0;
        (void)r;
    }
    vtx_runtime_destroy(&rt);
    free(hc);
    if (fused_bc) vtx_superinstruction_free(fused_bc);
    return sample_median(samples, nsamp);
}

/* ========================================================================== */
/* VORTEX benchmark dispatchers (one per kernel)                               */
/* ========================================================================== */

static uint64_t bench_vortex(int idx, int64_t N, int iters, int warmup) {
    switch (idx) {
    case 0: return vortex_run_bench(BENCH_FIB_ITER_CODE, BENCH_FIB_ITER_CODE_LEN,
                                    BENCH_FIB_ITER_CONSTS, BENCH_FIB_ITER_NCONSTS,
                                    BENCH_FIB_ITER_LOCALS, BENCH_FIB_ITER_STACK,
                                    N, iters, warmup);
    case 1: return vortex_run_bench(BENCH_LOOP_SUM_CODE, BENCH_LOOP_SUM_CODE_LEN,
                                    BENCH_LOOP_SUM_CONSTS, BENCH_LOOP_SUM_NCONSTS,
                                    BENCH_LOOP_SUM_LOCALS, BENCH_LOOP_SUM_STACK,
                                    N, iters, warmup);
    case 2: return vortex_run_bench(BENCH_TIGHT_LOOP_CODE, BENCH_TIGHT_LOOP_CODE_LEN,
                                    BENCH_TIGHT_LOOP_CONSTS, BENCH_TIGHT_LOOP_NCONSTS,
                                    BENCH_TIGHT_LOOP_LOCALS, BENCH_TIGHT_LOOP_STACK,
                                    N, iters, warmup);
    case 3: return vortex_run_bench(BENCH_BIT_OPS_CODE, BENCH_BIT_OPS_CODE_LEN,
                                    BENCH_BIT_OPS_CONSTS, BENCH_BIT_OPS_NCONSTS,
                                    BENCH_BIT_OPS_LOCALS, BENCH_BIT_OPS_STACK,
                                    N, iters, warmup);
    case 4: return vortex_run_bench(BENCH_GCD_LOOP_CODE, BENCH_GCD_LOOP_CODE_LEN,
                                    BENCH_GCD_LOOP_CONSTS, BENCH_GCD_LOOP_NCONSTS,
                                    BENCH_GCD_LOOP_LOCALS, BENCH_GCD_LOOP_STACK,
                                    N, iters, warmup);
    case 5: return vortex_run_bench(BENCH_COLLATZ_CODE, BENCH_COLLATZ_CODE_LEN,
                                    BENCH_COLLATZ_CONSTS, BENCH_COLLATZ_NCONSTS,
                                    BENCH_COLLATZ_LOCALS, BENCH_COLLATZ_STACK,
                                    N, iters, warmup);
    case 6: return vortex_run_bench(BENCH_FNV_HASH_CODE, BENCH_FNV_HASH_CODE_LEN,
                                    BENCH_FNV_HASH_CONSTS, BENCH_FNV_HASH_NCONSTS,
                                    BENCH_FNV_HASH_LOCALS, BENCH_FNV_HASH_STACK,
                                    N, iters, warmup);
    case 7: return vortex_run_bench(BENCH_ARITH_CHAIN_CODE, BENCH_ARITH_CHAIN_CODE_LEN,
                                    BENCH_ARITH_CHAIN_CONSTS, BENCH_ARITH_CHAIN_NCONSTS,
                                    BENCH_ARITH_CHAIN_LOCALS, BENCH_ARITH_CHAIN_STACK,
                                    N, iters, warmup);
    }
    return 0;
}

/* ========================================================================== */
/* C reference implementations                                                 */
/* ========================================================================== */

static int64_t c_fib_iter(int64_t n) {
    if (n <= 1) return n;
    int64_t a = 0, b = 1;
    for (int64_t i = 2; i <= n; i++) {
        int64_t t = a + b; a = b; b = t;
    }
    return b;
}
static int64_t c_loop_sum(int64_t n) {
    int64_t s = 0; for (int64_t i = 0; i < n; i++) s += i; return s;
}
static int64_t c_tight_loop(int64_t n) {
    int64_t i; for (i = 0; i < n; i++) {} return i;
}
static int64_t c_bit_ops(int64_t n) {
    int64_t x = (int64_t)0x9E3779B97F4A7C15LL;
    for (int64_t i = 0; i < n; i++) {
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
    }
    return x;
}
static int64_t c_gcd_loop(int64_t n) {
    int64_t g = 0;
    for (int64_t i = 0; i < n; i++) {
        int64_t a = i * 2 + 1, b = i * 3 + 2;
        while (a != 0 && b != 0) {
            if (a > b) a -= b; else b -= a;
        }
        g += a + b;
    }
    return g;
}
static int64_t c_collatz(int64_t n) {
    int64_t steps = 0, x = n;
    while (x > 1) {
        if (x & 1) x = 3*x + 1; else x = x / 2;
        steps++;
    }
    return steps;
}
static int64_t c_fnv_hash(int64_t n) {
    int64_t h = (int64_t)0xcbf29ce484222325LL;
    for (int64_t i = 0; i < n; i++) {
        h ^= i; h *= (int64_t)0x100000001b7LL;
    }
    return h;
}
static int64_t c_arith_chain(int64_t n) {
    int64_t acc = 0;
    for (int64_t i = 0; i < n; i++) {
        acc = (acc + 7) * 11 - 13;
    }
    return acc;
}

static uint64_t bench_c(int64_t (*fn)(int64_t), int64_t n, int iters, int warmup) {
    uint64_t samples[MAX_SAMPLES];
    int nsamp = (iters < MAX_SAMPLES) ? iters : MAX_SAMPLES;
    volatile int64_t sink = 0;
    for (int i = 0; i < warmup; i++) sink += fn(n + (i % 5));
    for (int i = 0; i < nsamp; i++) {
        int64_t nn = n + (i % 5);
        uint64_t t0 = now_ns();
        sink += fn(nn);
        uint64_t t1 = now_ns();
        samples[i] = t1 - t0;
    }
    (void)sink;
    return sample_median(samples, nsamp);
}

/* ========================================================================== */
/* Main                                                                        */
/* ========================================================================== */

typedef struct {
    const char *name;
    int64_t     N;
    int64_t     (*c_fn)(int64_t);
    uint64_t    vortex_ns;
    uint64_t    c_ns;
    int64_t     vortex_result;
    int64_t     c_result;
} bench_row_t;

int main(void) {
    printf("==============================================================\n");
    printf("  VORTEX vs V8 (Node.js) - Honest Benchmark Suite\n");
    printf("  All times: median over %d samples (varying input +/-4)\n", MAX_SAMPLES);
    printf("  VORTEX: T0 interpreter + T1 JIT (when emitter supports kernel)\n");
    printf("  C:      gcc -O3 -march=native -flto\n");
    printf("  V8:     node v24, TurboFan JIT (see JS companion)\n");
    printf("==============================================================\n\n");

    bench_init_all_consts();

    bench_row_t rows[] = {
        {"fib_iter(30)",      30,       c_fib_iter,     0, 0, 0, 0},
        {"loop_sum(10K)",     10000,    c_loop_sum,     0, 0, 0, 0},
        {"tight_loop(100K)",  100000,   c_tight_loop,   0, 0, 0, 0},
        {"bit_ops(100K)",     100000,   c_bit_ops,      0, 0, 0, 0},
        {"gcd_loop(1K)",      1000,     c_gcd_loop,     0, 0, 0, 0},
        {"collatz(1000)",     1000,     c_collatz,      0, 0, 0, 0},
        {"fnv_hash(100K)",    100000,   c_fnv_hash,     0, 0, 0, 0},
        {"arith_chain(100K)", 100000,   c_arith_chain,  0, 0, 0, 0},
    };
    const int nrows = (int)(sizeof(rows) / sizeof(rows[0]));

    /* VORTEX pass */
    for (int i = 0; i < nrows; i++) {
        printf("[VORTEX] %-22s ... ", rows[i].name); fflush(stdout);
        rows[i].vortex_ns = bench_vortex(i, rows[i].N, MAX_SAMPLES, 50);
        printf("%8.3f ms\n", ns_to_ms(rows[i].vortex_ns));
    }
    printf("\n");

    /* C pass */
    for (int i = 0; i < nrows; i++) {
        printf("[C]      %-22s ... ", rows[i].name); fflush(stdout);
        rows[i].c_ns = bench_c(rows[i].c_fn, rows[i].N, MAX_SAMPLES, 50);
        printf("%8.4f ms\n", ns_to_ms(rows[i].c_ns));
    }

    /* Final table */
    printf("\n");
    printf("==============================================================\n");
    printf("  RESULTS - VORTEX vs C vs V8 (run JS separately)\n");
    printf("==============================================================\n");
    printf("  %-22s  %12s  %12s  %12s  %8s  %8s\n",
           "Benchmark", "VORTEX (ms)", "C (ms)", "V8 (ms)", "V/C", "V/V8");
    printf("  %-22s  %12s  %12s  %12s  %8s  %8s\n",
           "----------", "----------", "----------", "----------", "------", "------");
    for (int i = 0; i < nrows; i++) {
        double v = ns_to_ms(rows[i].vortex_ns);
        double c = ns_to_ms(rows[i].c_ns);
        double vc = (c > 0) ? v / c : 0;
        printf("  %-22s  %12.3f  %12.4f  %12s  %7.2fx  %8s\n",
               rows[i].name, v, c, "(run JS)", vc, "(run JS)");
    }
    printf("\n  V8 (Node.js) results: run `node benchmarks/v8_js/bench_v8_comparison.js`\n");
    printf("  Or run the comparison script: python3 scripts/run_v8_comparison.py\n");
    printf("==============================================================\n");

    return 0;
}
